const toast=document.getElementById('toast');let timer;
function message(text){toast.textContent=text;toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),4200)}
async function copy(text,success){try{await navigator.clipboard.writeText(text);message(success)}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();message(ok?success:'Copy unavailable. Please select and copy the text manually.')}}
const pageURL=()=>location.origin+location.pathname;
const caption=()=>`A new battle. The same faithful God. ❤️\n\nAte Jhen (Jennifer Pulido) is facing Acute Myeloid Leukemia. Let’s stand with her family through prayer, giving, and blood donation.\n\nGCash: Dante Pulido — 0917 140 4945\nBlood: PRBC & platelets | PGH, Room 744 | Patient blood type O+\nDonation hours shared by the family: 6 AM–12 noon, Monday–Sunday. Bring a picture or photocopy of her Blue Card; the blood bank determines donor eligibility.\n\nRead her story and find ways to help: ${pageURL()}`;
document.getElementById('copy-number').onclick=()=>copy('09171404945','GCash number copied: 09171404945');
document.getElementById('copy-link').onclick=()=>copy(pageURL(),'Page link copied. Thank you for sharing.');
document.getElementById('share-ig').onclick=()=>copy(caption(),'Caption copied. Paste it into your Instagram post or story.');
document.getElementById('share-fb').onclick=()=>window.open('https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(pageURL()),'_blank','noopener,noreferrer');
document.getElementById('share-native').onclick=async()=>{if(navigator.share){try{await navigator.share({title:'Stand with Ate Jhen',text:'A new battle. The same faithful God. Help through prayer, giving, and blood donation.',url:pageURL()})}catch(e){if(e.name!=='AbortError')await copy(caption(),'Story and link copied.')}}else await copy(caption(),'Story and link copied. Share them with someone who can help.')};
const dialog=document.getElementById('photo-dialog');document.querySelectorAll('[data-photo]').forEach(button=>button.onclick=()=>{document.getElementById('dialog-image').src=button.dataset.photo;document.getElementById('dialog-image').alt=button.dataset.caption;document.getElementById('dialog-caption').textContent=button.dataset.caption;dialog.showModal()});document.getElementById('close-photo').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
